<?php
require __DIR__.'/_auth.php';$pdo=admin_db();if(!$pdo)exit('Database unavailable.');$id=(int)($_GET['id']??0);$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'save';if($action==='delete'&&$id){$pdo->prepare('DELETE FROM articles WHERE id=?')->execute([$id]);header('Location:/admin/articles.php');exit;}$title=trim($_POST['title']??'');$slug=preg_replace('/[^a-z0-9-]+/','-',strtolower(trim($_POST['slug']??$title)));$status=($_POST['status']??'draft')==='published'?'published':'draft';$published=$status==='published'?date('Y-m-d H:i:s'):null;$data=[$slug,$title,trim($_POST['excerpt']??''),trim($_POST['body']??''),trim($_POST['featured_image']??''),$status,$published,trim($_POST['meta_title']??''),trim($_POST['meta_description']??'')];if($id){$st=$pdo->prepare('UPDATE articles SET slug=?,title=?,excerpt=?,body=?,featured_image=?,status=?,published_at=COALESCE(published_at,?),meta_title=?,meta_description=?,updated_at=NOW() WHERE id=?');$st->execute([...$data,$id]);}else{$st=$pdo->prepare('INSERT INTO articles(slug,title,excerpt,body,featured_image,status,published_at,meta_title,meta_description,updated_at) VALUES(?,?,?,?,?,?,?,?,?,NOW())');$st->execute($data);$id=(int)$pdo->lastInsertId();}$msg='Article saved.';}
$article=null;if($id){$st=$pdo->prepare('SELECT * FROM articles WHERE id=?');$st->execute([$id]);$article=$st->fetch();}$list=$pdo->query('SELECT id,title,slug,status,updated_at FROM articles ORDER BY updated_at DESC')->fetchAll();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><link rel="stylesheet" href="/assets/css/style.css"><title>Articles CMS</title></head><body><main class="section wrap"><div class="section-head"><div><span class="eyebrow dark-text">CMS</span><h1>Travel Guide Articles</h1></div><div><a class="btn light" href="/admin/">Dashboard</a> <a class="btn dark" href="/admin/articles.php">New Article</a></div></div><?php if($msg):?><p><strong><?=e($msg)?></strong></p><?php endif;?><div class="content-layout"><section><form class="contact-form" method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input name="title" value="<?=e($article['title']??'')?>" placeholder="Article title" required><input name="slug" value="<?=e($article['slug']??'')?>" placeholder="slug"><textarea name="excerpt" placeholder="Short excerpt"><?=e($article['excerpt']??'')?></textarea><textarea name="body" style="min-height:360px" placeholder="Article body"><?=e($article['body']??'')?></textarea><input name="featured_image" value="<?=e($article['featured_image']??'')?>" placeholder="Featured image path"><input name="meta_title" value="<?=e($article['meta_title']??'')?>" placeholder="SEO title"><textarea name="meta_description" placeholder="SEO description"><?=e($article['meta_description']??'')?></textarea><select name="status"><option value="draft" <?=($article['status']??'draft')==='draft'?'selected':''?>>Draft</option><option value="published" <?=($article['status']??'')==='published'?'selected':''?>>Published</option></select><button class="btn gold">Save Article</button><?php if($id):?><button class="btn" name="action" value="delete" onclick="return confirm('Delete this article?')">Delete</button><?php endif;?></form></section><aside><h2>Existing Articles</h2><?php foreach($list as $r):?><p><a href="/admin/articles.php?id=<?=$r['id']?>"><strong><?=e($r['title'])?></strong></a><br><small>/article/<?=e($r['slug'])?> · <?=e($r['status'])?></small></p><?php endforeach;?></aside></div></main></body></html>
